using System.Threading;

private int _refs;

public bool TryAcquire() =>
    Interlocked.CompareExchange(ref _refs, 1, 0) == 0;

// publish immutable state: plain write + release, then acquire on the reader side
private Node? _head;
public void Publish(Node n)
{
    n.Next = Volatile.Read(ref _head);       // acquire: read the current head safely
    Volatile.Write(ref _head, n);            // release: publish n and its Next
}
public Node? Take() => Interlocked.Exchange(ref _head, null);
